package org.apache.commons.codec.language;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.codec.EncoderException;
import org.apache.commons.codec.StringEncoder;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Metaphone_metaphone_TriageGen2Test {

    private Metaphone metaphone;

    @Before
    public void setUp() {
        metaphone = new Metaphone();
    }

    @Test
    public void testMetaphone_NullAndEmpty() {
        assertEquals("", metaphone.metaphone(null));
        assertEquals("", metaphone.metaphone(""));
    }

    @Test
    public void testMetaphone_SingleChar() {
        assertEquals("A", metaphone.metaphone("a"));
        assertEquals("Z", metaphone.metaphone("z"));
    }

    @Test
    public void testMetaphone_InitialExceptions() {
        // KN -> N
        assertEquals("N", metaphone.metaphone("KNIGHT"));
        // GN -> G (handled in loop, but testing K/G/P initial logic)
        assertEquals("K", metaphone.metaphone("KATE"));
        // AE -> E
        assertEquals("E", metaphone.metaphone("AERIE"));
        // WR -> R
        assertEquals("R", metaphone.metaphone("WRITER"));
        // WH -> W
        assertEquals("W", metaphone.metaphone("WHALE"));
        // X -> S
        assertEquals("S", metaphone.metaphone("XEROX"));
    }

    @Test
    public void testMetaphone_VowelsAndDuplicates() {
        // Leading vowel
        assertEquals("A", metaphone.metaphone("APPLE"));
        // Duplicate letters (except C)
        assertEquals("P", metaphone.metaphone("APPLE")); // P is duplicate, but logic handles it
        assertEquals("L", metaphone.metaphone("BALL"));
    }

    @Test
    public void testMetaphone_B_Logic() {
        // MB at end -> silent B
        assertEquals("M", metaphone.metaphone("COMB"));
        // B not at end
        assertEquals("B", metaphone.metaphone("BABY"));
    }

    @Test
    public void testMetaphone_C_Logic() {
        // SCI, SCE, SCY -> discard C
        assertEquals("S", metaphone.metaphone("SCENE"));
        // CIA -> X
        assertEquals("X", metaphone.metaphone("CIA"));
        // CI, CE, CY -> S
        assertEquals("S", metaphone.metaphone("CITY"));
        // SCH -> K
        assertEquals("K", metaphone.metaphone("SCHEME"));
        // CH (consonant) -> K
        assertEquals("K", metaphone.metaphone("CHARACTER"));
        // CH (vowel) -> X
        assertEquals("X", metaphone.metaphone("CHURCH"));
        // Standard C -> K
        assertEquals("K", metaphone.metaphone("CAT"));
    }

    @Test
    public void testMetaphone_D_Logic() {
        // DGE, DGI, DGY -> J
        assertEquals("J", metaphone.metaphone("BRIDGE"));
        // Standard D -> T
        assertEquals("T", metaphone.metaphone("DOG"));
    }

    @Test
    public void testMetaphone_G_Logic() {
        // GH silent at end
        assertEquals("K", metaphone.metaphone("HIGH")); // G is silent, H is terminal
        // GH before consonant
        assertEquals("K", metaphone.metaphone("GHOST"));
        // GN/GNED -> silent G
        assertEquals("N", metaphone.metaphone("GNAT"));
        // G before vowel -> J/K logic
        assertEquals("J", metaphone.metaphone("GIN"));
        assertEquals("K", metaphone.metaphone("GAT"));
    }

    @Test
    public void testMetaphone_H_Logic() {
        // Terminal H
        assertEquals("A", metaphone.metaphone("AHA")); 
        // H after vowel
        assertEquals("H", metaphone.metaphone("OH"));
        // H after consonant (VARSON check)
        assertEquals("A", metaphone.metaphone("AH"));
    }

    @Test
    public void testMetaphone_P_Logic() {
        // PH -> F
        assertEquals("F", metaphone.metaphone("PHONE"));
        // Standard P
        assertEquals("P", metaphone.metaphone("PAN"));
    }

    @Test
    public void testMetaphone_Q_Logic() {
        assertEquals("K", metaphone.metaphone("QUICK"));
    }

    @Test
    public void testMetaphone_S_Logic() {
        // SH, SIO, SIA -> X
        assertEquals("X", metaphone.metaphone("SHOE"));
        assertEquals("X", metaphone.metaphone("SION"));
        assertEquals("X", metaphone.metaphone("SIA"));
        // Standard S
        assertEquals("S", metaphone.metaphone("SUN"));
    }

    @Test
    public void testMetaphone_T_Logic() {
        // TIA, TIO -> X
        assertEquals("X", metaphone.metaphone("TIA"));
        // TCH -> silent T
        assertEquals("CH", metaphone.metaphone("WATCH")); 
        // TH -> 0
        assertEquals("0", metaphone.metaphone("THEN"));
        // Standard T
        assertEquals("T", metaphone.metaphone("TEN"));
    }

    @Test
    public void testMetaphone_V_Z_X_W_Y_Logic() {
        // V -> F
        assertEquals("F", metaphone.metaphone("VINE"));
        // Z -> S
        assertEquals("S", metaphone.metaphone("ZEBRA"));
        // X -> KS
        assertEquals("KS", metaphone.metaphone("XRAY"));
        // W/Y followed by vowel
        assertEquals("W", metaphone.metaphone("WAVE"));
        assertEquals("Y", metaphone.metaphone("YARD"));
        // W/Y not followed by vowel (silent)
        assertEquals("", metaphone.metaphone("W")); // Handled by single char, testing logic via longer
        assertEquals("R", metaphone.metaphone("WR")); // Handled by initial exception
    }

    @Test
    public void testMetaphone_MaxLen() {
        metaphone.setMaxCodeLen(2);
        String result = metaphone.metaphone("METAPHONE");
        assertTrue(result.length() <= 2);
    }
}
